176	  const events = (history ?? []) as MetaEvent[];
177	  const latestVersion = new Map<string, number>();
178	  for (const event of events) if (!event.undone_at && !event.undo_of)
179	    latestVersion.set(event.entity_id, Math.max(latestVersion.get(event.entity_id) ?? 0, Number(event.after?.version ?? 0)));
180	  const canUndo = (event: MetaEvent) => !event.undone_at && !event.undo_of && versions.has(event.entity_id) && Number(event.after?.version ?? 0) >= (latestVersion.get(event.entity_id) ?? 0);
181	  const when = new Intl.DateTimeFormat(locale, { timeZone, dateStyle: "medium", timeStyle: "short" });
182	  return events.length ? <section><h2 className="text-sm font-medium text-muted-foreground">Account and saved view history</h2>
