import type { SupabaseClient } from "@supabase/supabase-js";

type Connection = { name: string; status: string; last_error: string | null; historyMissing?: boolean };

export function syncProblems(connections: Connection[]) {
  const active = new Set(connections.filter(row => row.status === "active").map(row => row.name));
  return [...new Set(connections.flatMap(({ name, status, last_error, historyMissing }) => {
    if (status !== "active") return active.has(name) ? [] : [`${name} needs reconnecting, so its numbers may be old.`];
    if (last_error && historyMissing) return [`${name} hasn't sent its transaction history yet, so its numbers are incomplete. Moneo tries again by itself.`];
    return last_error ? [`${name} could not sync, so its numbers may be old. Moneo tries again by itself.`] : [];
  }))];
}

export async function loadSyncProblems(db: SupabaseClient, workspaceId: string) {
  const live = ["active", "expired", "error"];
  const [banks, scalable] = await Promise.all([
    db.from("bank_connections").select("aspsp_name, status, last_error, accounts:bank_connection_accounts(last_booked_on, last_error)").eq("workspace_id", workspaceId).in("status", live),
    db.from("scalable_connections").select("status, last_error").eq("workspace_id", workspaceId).in("status", live),
  ]);
  return syncProblems([...(banks.data ?? []).map(({ aspsp_name, accounts, ...row }) =>
    ({ ...row, name: aspsp_name, historyMissing: accounts.some(account => account.last_error && !account.last_booked_on) })), ...(scalable.data ?? []).map(row => ({ ...row, name: "Scalable" }))]);
}
import { NextResponse } from "next/server";
import { requireWorkspace } from "@/lib/auth";
import { enableBankingConfigured } from "@/lib/bank/enable-banking";
import { BANK_REDIRECT_URL } from "@/lib/bank/return-listener";
import { syncRunning } from "@/lib/bank/sync-state";
import { serviceKeyStatus } from "@/lib/service-keys";

type SyncImport = { id: string; status: string; total_rows: number; new_rows: number; matched_rows: number; review_rows: number; rejected_rows: number; created_at: string; mapping: { accountName?: string } | null };

export async function GET() {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return NextResponse.json({ error: "Unauthorized" }, { status: 401 }); }
  const { data, error } = await context.supabase.from("bank_connections")
    .select("id, aspsp_name, aspsp_country, status, valid_until, last_synced_at, sync_started_at, last_error, accounts:bank_connection_accounts(provider_account_uid, account_name, currency_code, last_booked_on)")
    .eq("workspace_id", context.workspace.id).in("status", ["active", "expired", "error"]).order("created_at", { ascending: false });
  if (error) return NextResponse.json({ error: "Connected banks are unavailable" }, { status: 500 });
  const starts = data.map(connection => connection.sync_started_at).filter((start): start is string => !!start).sort();
  let imports: SyncImport[] = [];
  if (starts.length) {
    const recent = await context.supabase.from("imports").select("id, status, total_rows, new_rows, matched_rows, review_rows, rejected_rows, created_at, mapping")
      .eq("workspace_id", context.workspace.id).gte("created_at", starts[0]).order("created_at");
    if (recent.error) return NextResponse.json({ error: "Connected banks are unavailable" }, { status: 500 });
    imports = recent.data as SyncImport[];
  }
  const connections = data.map(connection => {
    const names = new Set(connection.accounts.map(account => account.account_name));
    const started = connection.sync_started_at ? Date.parse(connection.sync_started_at) : Infinity;
    const own = imports.filter(item => Date.parse(item.created_at) >= started && names.has(item.mapping?.accountName ?? ""));
    return { ...connection, sync: { running: syncRunning(connection), imports: own.map(item => ({ id: item.id, status: item.status, total_rows: item.total_rows, new_rows: item.new_rows, matched_rows: item.matched_rows, review_rows: item.review_rows, rejected_rows: item.rejected_rows })) } };
  });
  const [configured, keys] = await Promise.all([enableBankingConfigured(), serviceKeyStatus()]);
  return NextResponse.json({ configured, credentials: keys.enable_banking_app_id, redirectUrl: BANK_REDIRECT_URL, connections });
}
import { NextResponse } from "next/server";
import { requireWorkspace } from "@/lib/auth";
import { scalableConfigured } from "@/lib/scalable/server";
import { jsonObject } from "@/lib/database";

export async function GET() {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return NextResponse.json({ error: "Unauthorized" }, { status: 401 }); }
  const { data, error } = await context.supabase.from("scalable_connections").select("id, status, last_synced_at, last_error, created_at, portfolio")
    .eq("workspace_id", context.workspace.id).in("status", ["active", "expired", "error"]).order("created_at", { ascending: false }).limit(1);
  if (error) return NextResponse.json({ error: "Scalable status is unavailable" }, { status: 500 });
  const portfolio = jsonObject.safeParse(data[0]?.portfolio);
  const connection = data[0] ? { ...data[0], portfolio: portfolio.success ? { ...portfolio.data, itemIds: undefined } : null } : null;
  return NextResponse.json({ configured: scalableConfigured(), connection });
}
import { NextResponse } from "next/server";
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { connectionReturn } from "@/lib/desktop-bridge";
import { serviceDb } from "@/lib/service-db";
import { decryptToken } from "@/lib/bank/token-crypto";
import { exchangeCode } from "@/lib/scalable/client";
import { sealTokens } from "@/lib/scalable/server";
import { syncScalable } from "@/lib/scalable/sync";

const syncFailureIsStoredOnTheConnection = () => undefined;

const querySchema = z.object({ state: z.string().uuid(), code: z.string().min(1).max(2000).optional(), error: z.string().max(200).optional() });

export async function GET(request: Request) {
  const back = (result: string) => connectionReturn(request.url, `/import?scalable=${result}#scalable`);
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return NextResponse.redirect(new URL("/setup", request.url), 303); }
  const query = querySchema.safeParse(Object.fromEntries(new URL(request.url).searchParams));
  if (!query.success) return back("invalid");
  const db = serviceDb();
  const workspaceId = context.workspace.id;
  const pending = await db.from("scalable_connections").select("id, client_id, redirect_uri, pkce_verifier_encrypted, created_at")
    .eq("auth_state", query.data.state).eq("workspace_id", workspaceId).eq("status", "pending").maybeSingle();
  if (pending.error || !pending.data?.pkce_verifier_encrypted || Date.now() - Date.parse(pending.data.created_at) > 3_600_000) return back("invalid");
  const connectionId: string = pending.data.id;
  const fail = async (message: string) => {
    await db.from("scalable_connections").update({ status: "error", last_error: message, pkce_verifier_encrypted: null }).eq("id", connectionId).eq("status", "pending");
    return back("error");
  };
  if (!query.data.code || query.data.error) return fail(query.data.error ? `Scalable returned ${query.data.error}` : "Scalable did not return a login code");
  try {
    const tokens = await exchangeCode({ clientId: pending.data.client_id, redirectUri: pending.data.redirect_uri, code: query.data.code,
      verifier: decryptToken(pending.data.pkce_verifier_encrypted, connectionId) });
    const activated = await db.from("scalable_connections").update({ status: "active", tokens_encrypted: sealTokens(tokens, connectionId),
      pkce_verifier_encrypted: null, last_error: null }).eq("id", connectionId).eq("status", "pending").select("id").single();
    if (activated.error) throw activated.error;
    await db.from("scalable_connections").update({ status: "revoked", tokens_encrypted: null }).eq("workspace_id", workspaceId)
      .in("status", ["active", "expired", "error"]).neq("id", connectionId);
    await syncScalable(connectionId, workspaceId).catch(syncFailureIsStoredOnTheConnection);
    return back("connected");
  } catch {
    return fail("The Scalable login could not be completed");
  }
}
