import { cronSecret, loopbackUrl } from "@/lib/env";

export const CRON_JOBS = ["/api/cron/summaries", "/api/cron/reviews", "/api/cron/agent-backlog", "/api/cron/bank-sync", "/api/cron/scalable-sync", "/api/cron/scalable-history", "/api/cron/chat-titles"] as const;
const HOUR = 3_600_000, FIRST_RUN = 60_000;

export async function runCronJobs(baseUrl: string, secret: string, fetcher: typeof fetch = fetch) {
  for (const path of CRON_JOBS) {
    try {
      const response = await fetcher(new URL(path, baseUrl), { headers: { authorization: `Bearer ${secret}` }, signal: AbortSignal.timeout(300_000) });
      if (!response.ok && response.status !== 503) console.warn(`Scheduled job ${path} returned ${response.status}`);
    } catch (error) {
      console.warn(`Scheduled job ${path} failed`, error instanceof Error ? error.message : error);
    }
  }
}

export function startScheduler(env?: NodeJS.ProcessEnv) {
  const secret = cronSecret(env);
  if (!secret) return null;
  const baseUrl = loopbackUrl(env);
  let running = false;
  const tick = async () => {
    if (running) return;
    running = true;
    try { await runCronJobs(baseUrl, secret); } finally { running = false; }
  };
  const first = setTimeout(() => void tick(), FIRST_RUN);
  const hourly = setInterval(() => void tick(), HOUR);
  first.unref(); hourly.unref();
  return () => { clearTimeout(first); clearInterval(hourly); };
}
import { cronRoute } from "@/lib/cron";
import { enableBankingConfigured } from "@/lib/bank/enable-banking";
import { serviceDb } from "@/lib/service-db";
import { startBankSync } from "@/lib/bank/start-sync";
import { ALIGNED_SPACING_MS, accountDue } from "@/lib/bank/sync-state";
import { serviceRoleConfig } from "@/lib/env";

export const maxDuration = 60;

export const GET = cronRoute(async () => {
  if (!serviceRoleConfig() || !(await enableBankingConfigured())) return Response.json({ error: "Bank sync unavailable" }, { status: 503 });
  const { data, error } = await serviceDb().from("bank_connection_accounts").select("connection_id, workspace_id, last_attempted_at, next_allowed_at, bank_connections!inner(status)")
    .eq("bank_connections.status", "active").order("connection_id").limit(1000);
  if (error) return Response.json({ error: "Bank connections unavailable" }, { status: 503 });
  const now = Date.now(), rows = data ?? [];
  const workspaces = new Set(rows.filter(row => accountDue(row, false, now)).map(row => row.workspace_id));
  const due = new Map<string, string>();
  for (const row of rows) if (workspaces.has(row.workspace_id) && accountDue(row, false, now, ALIGNED_SPACING_MS)) due.set(row.connection_id, row.workspace_id);
  let started = 0, busy = 0, failed = 0;
  for (const [connectionId, workspaceId] of due) {
    try { if (await startBankSync(connectionId, workspaceId, undefined, true)) started++; else busy++; }
    catch { failed++; }
  }
  return Response.json({ started, busy, failed });
});
