import { chromium } from "@playwright/test";
import { execSync } from "node:child_process";

const base = "http://localhost:3107", out = ".qa/shots/after";
const S = process.argv[2];
const seed = file => execSync(`docker exec -i moneo-qa-db-1 psql -v ON_ERROR_STOP=1 -U postgres -d postgres`, { input: execSync(`cat ${S}/${file}`) });
const browser = await chromium.launch();
const errors = [];
async function view(name, scheme, mobile, run) {
  const context = await browser.newContext({ storageState: "e2e/.auth.json", colorScheme: scheme, viewport: mobile ? { width: 390, height: 844 } : { width: 1280, height: 900 },
    extraHTTPHeaders: { "x-moneo-test": "1" } });
  const page = await context.newPage();
  page.on("console", m => { if (m.type() === "error") errors.push(`${name}: ${m.text()}`); });
  await page.route("**/api/bank/aspsps?country=*", r => r.fulfill({ json: { banks: ["Testbank", "Other Bank", "Sparkasse Testhausen", "Volksbank Beispiel"].map(n => ({ name: n, country: "DE" })) } }));
  await run(page);
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `${out}/${name}-${mobile ? "mobile" : scheme}.png`, fullPage: true });
  await context.close();
}
const configured = page => page.route("**/api/bank/connections", async r => { const res = await r.fetch(); const json = await res.json();
  await r.fulfill({ json: { ...json, configured: true, credentials: { source: "app", hint: "f00d" } } }); });
const all = async (name, run) => { for (const [s, m] of [["light", false], ["dark", false], ["light", true]]) await view(name, s, m, run); };

await all("stage1-empty", async p => { await p.goto(`${base}/money/accounts`); });
await all("stage2-enable-banking-setup", async p => { await p.goto(`${base}/money/accounts?connect=bank#connected`); });
await all("stage3-bank-picker", async p => { await configured(p); await p.goto(`${base}/money/accounts?connect=bank#connected`); await p.getByLabel("Search").fill("bank"); });
await all("stage3b-add-account-menu", async p => { await p.goto(`${base}/money/accounts`); await p.getByText("Add account", { exact: true }).click(); });
seed("seed-one.sql");
await all("stage4-one-bank", async p => { await configured(p); await p.goto(`${base}/money/accounts?bank=connected#connected`); });
seed("seed-two.sql");
await all("stage5-two-banks", async p => { await configured(p); await p.goto(`${base}/money/accounts`); });
await all("settings", async p => { await p.goto(`${base}/settings`); });
await all("import", async p => { await p.goto(`${base}/import`); });
console.log(errors.join("\n") || "no console errors");
await browser.close();

